p='features/summary/summary.slot.tsx'
s=open(p).read()
s=s.replace('''  const dueOf = (personId: string) => {
    const p = people.find((q) => q.id === personId)!;
    return personDueTotal(rates, p.grades, today, claims.filter((c) => c.personId === p.id), p.held, floor, late);
  };
''','''  const dueOf = (p: Person) =>
    personDueTotal(rates, p.grades, today, claims.filter((c) => c.personId === p.id), p.held, floor, late);
